if(b.id==='payConsultationFee'&&s.page==='consultation-payment'&&s.loggedIn&&s.feeTerms){if(!validateBookingContact())return;s.feePaid=true;s.feeCreditRemaining=s.consultationFee;go('booked');return}
if(b.id==='clearScans'){s.captures={};s.shared=false;s.scanning=null;s.scanConsent=false;s.privacyMessage='Scan previews and sharing consent cleared from this session.';render();return}
if(b.id==='paymentSignIn'){s.authReturn='payment';s.loginStage='email';go('login');return}
if(b.id==='loginEmail'){s.loginStage='code';render();return}
if(b.id==='loginConfirm'||b.id==='loginApple'||b.id==='loginGoogle'){s.loggedIn=true;s.loginStage='email';go(s.authReturn);s.authReturn='profile';return}
if(b.id==='signOut'){s.loggedIn=false;s.authReturn='profile';s.loginStage='email';go('login');return}
if(b.id==='removePrescription'){prescriptionGeneration++;s.prescription=null;saveCollection();prescriptionFile=null;prescriptionMessage='';const scroll=selectionScroll();render();restoreSelectionScroll(scroll);return}if(b.id==='addCart'){if(prescriptionBusy)return;if(s.editingCart!==null&&s.cart[s.editingCart]){s.cart[s.editingCart]={...pairSnapshot(),quantity:s.cart[s.editingCart].quantity};s.editingCart=null;saveCollection()}else addPairToCart(pairSnapshot());prescriptionGeneration++;s.prescription=null;prescriptionFile=null;prescriptionMessage='';saveCollection();go('cart');return}if(b.id==='checkoutCart'&&s.cart.length){s.checkoutCart=true;go('checkout');return}
if(d.savedOpen!==undefined||d.cartEdit!==undefined){const pair=d.savedOpen!==undefined?s.savedPairs[Number(d.savedOpen)]:s.cart[Number(d.cartEdit)];if(pair){restorePair(pair);s.editingCart=d.cartEdit!==undefined?Number(d.cartEdit):null;s.checkoutCart=false;go('custom')}return}
if(d.savedRemove!==undefined){const pair=s.savedPairs.splice(Number(d.savedRemove),1)[0];if(pair)s.liked[pair.key]=false;saveCollection();render();return}
if(d.savedAdd!==undefined){const pair=s.savedPairs[Number(d.savedAdd)];if(pair){addPairToCart(pair);go('cart')}return}
if(d.cartRemove!==undefined){s.cart.splice(Number(d.cartRemove),1);saveCollection();render();return}
if(d.cartQuantity!==undefined){const pair=s.cart[Number(d.cartQuantity)];if(pair){pair.quantity=Math.min(99,pair.quantity+Number(d.delta));if(pair.quantity<1)s.cart.splice(Number(d.cartQuantity),1);saveCollection();render()}return}
if(d.choice){chooseOption(d.choice,d.value);return;}if(d.go){if(d.go==='login'&&s.page==='profile')s.authReturn='profile';if(d.go==='booking-fee'){s.reason='Essence consultation';s.feePaid=false;}if(d.go==='privacy')s.privacyReturn=s.page;if(d.go==='checkout'&&!['payment','checkout'].includes(s.page))s.checkoutCart=false;go(d.go);}if(d.inspect||d.board){s.scanning=null;s.page=d.inspect||d.board;history=[];rescan=false;render();if(d.inspect)document.body.classList.remove('overview')}
